INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5142943, 747849, 98339, '<td valign="top">I like this...how many shots did it take...</td>', 'I like this...how many shots did it take...', '2008-12-20 16:21:19.000000', NULL, 1),
(5142946, 747938, 98339, '<td valign="top">That''s good...</td>', 'That''s good...', '2008-12-20 16:22:03.000000', NULL, 1),
(5142948, 747607, 22459, '<td valign="top">Bumping up :) good idea for the challnge such a cute face. Technically a very well executed shot.</td>', 'Bumping up :) good idea for the challnge such a cute face. Technically a very well executed shot.', '2008-12-20 16:22:19.000000', NULL, 1),
(5142950, 748010, 22459, '<td valign="top">interesting take on the challenge and well executed.</td>', 'interesting take on the challenge and well executed.', '2008-12-20 16:22:33.000000', NULL, 1),
(5142951, 747222, 98339, '<td valign="top">nice shot</td>', 'nice shot', '2008-12-20 16:23:10.000000', NULL, 1),
(5142955, 747906, 22459, '<td valign="top">back for comment and bumping up :) nice b/w and great take on the challenge just one small disappointment is the close crop at the top, it would have been better composition wise with a bit more space at the top.</td>', 'back for comment and bumping up :) nice b/w and great take on the challenge just one small disappointment is the close crop at the top, it would have been better composition wise with a bit more space at the top.', '2008-12-20 16:27:28.000000', NULL, 1),
(5142958, 746949, 98339, '<td valign="top">is that a blood orange?????</td>', 'is that a blood orange?????', '2008-12-20 16:28:23.000000', NULL, 1),
(5142963, 747753, 22459, '<td valign="top">back to comment and bumping up :) This is a really nice image and great take on the challenge. I love how you have used an everyday item to display personification and the b/w works a treat in conveying the mood.(10)</td>', 'back to comment and bumping up :) This is a really nice image and great take on the challenge. I love how you have used an everyday item to display personification and the b/w works a treat in conveying the mood.(10)', '2008-12-20 16:30:56.000000', NULL, 1),
(5143171, 747528, 99411, '<td valign="top">Love the composition and colours.  Gets a 10 from me</td>', 'Love the composition and colours.  Gets a 10 from me', '2008-12-20 18:52:24.000000', NULL, 1),
(5143172, 747873, 99411, '<td valign="top">Probably the best natural personification in the challenge.  Gets a great score from me. Nice shot.  Can''t help wondering if a different crop would score higher.</td>', 'Probably the best natural personification in the challenge.  Gets a great score from me. Nice shot.  Can''t help wondering if a different crop would score higher.', '2008-12-20 18:53:52.000000', NULL, 1),
(5143174, 747815, 99411, '<td valign="top">happy faces = high scores.  great shot that makes the viewer smile, should do well</td>', 'happy faces = high scores.  great shot that makes the viewer smile, should do well', '2008-12-20 18:54:37.000000', NULL, 1),
(5143175, 747906, 99411, '<td valign="top">brilliant, simply brilliant</td>', 'brilliant, simply brilliant', '2008-12-20 18:54:56.000000', NULL, 1),
(5143177, 747751, 99411, '<td valign="top">great idea, well executed.  Not sure about the crop/trees</td>', 'great idea, well executed.  Not sure about the crop/trees', '2008-12-20 18:55:38.000000', NULL, 1),
(5143181, 747284, 99411, '<td valign="top">great idea that has been well executed.  Should ribbon.  Gets a good score from me</td>', 'great idea that has been well executed.  Should ribbon.  Gets a good score from me', '2008-12-20 18:56:54.000000', NULL, 1),
(5143182, 747753, 99411, '<td valign="top">simple but effective</td>', 'simple but effective', '2008-12-20 18:57:21.000000', NULL, 1),
(5143184, 747727, 99411, '<td valign="top">I looked everywhere for a tree like this.  Great shot.  Will be v interested to see how you score</td>', 'I looked everywhere for a tree like this.  Great shot.  Will be v interested to see how you score', '2008-12-20 18:58:03.000000', NULL, 1),
(5143185, 747308, 99411, '<td valign="top">nice twist, v topical</td>', 'nice twist, v topical', '2008-12-20 18:58:19.000000', NULL, 1),
(5143187, 747951, 99411, '<td valign="top">Now how did you come up with this?   Why do I not have your imagination. Great shot.  Just a week too early for the shadow comp.  should do well</td>', 'Now how did you come up with this?   Why do I not have your imagination. Great shot.  Just a week too early for the shadow comp.  should do well', '2008-12-20 18:59:52.000000', NULL, 1),
(5143191, 747607, 99411, '<td valign="top">well executed, but a direct copy f a previous entry into personification.  Although your version is much better executed.</td>', 'well executed, but a direct copy f a previous entry into personification.  Although your version is much better executed.', '2008-12-20 19:01:00.000000', NULL, 1),
(5143196, 747220, 99411, '<td valign="top">Great shot, well executed.  However, this theme was done in a previous personification challenge.  Will it negatively impact your score?  will watch with interest.  However your version is better executed by far. Like the title too</td>', 'Great shot, well executed.  However, this theme was done in a previous personification challenge.  Will it negatively impact your score?  will watch with interest.  However your version is better executed by far. Like the title too', '2008-12-20 19:02:41.000000', NULL, 1),
(5143199, 747975, 99411, '<td valign="top">great idea, well executed</td>', 'great idea, well executed', '2008-12-20 19:03:05.000000', NULL, 1),
(5143200, 747222, 99411, '<td valign="top">cute and effective</td>', 'cute and effective', '2008-12-20 19:03:17.000000', NULL, 1),
(5143313, 747473, 57460, '<td valign="top">I love the concept of the photo - I love crayola crayons!  The main thing that takes it away for me is that I can see the tape holding the crayons - maybe next time try either pins or even small nails, stuck through the bottom of a piece of poster board, then stick the crayon on top of that - this is what I did with crayola markers once and it worked well to hold them up.  Good job and good luck!</td>', 'I love the concept of the photo - I love crayola crayons!  The main thing that takes it away for me is that I can see the tape holding the crayons - maybe next time try either pins or even small nails, stuck through the bottom of a piece of poster board, then stick the crayon on top of that - this is what I did with crayola markers once and it worked well to hold them up.  Good job and good luck!', '2008-12-20 21:27:08.000000', NULL, 1),
(5143487, 747713, 50695, '<td valign="top">Gorgeous. You know who you are.</td>', 'Gorgeous. You know who you are.', '2008-12-21 00:11:42.000000', NULL, 1),
(5143489, 747473, 50695, '<td valign="top">I hate shots like this, but you have the "comforter" and the "peeper"... you''ve even got some perv underssing. These crayons have come to life! 6</td>', 'I hate shots like this, but you have the "comforter" and the "peeper"... you''ve even got some perv underssing. These crayons have come to life! 6', '2008-12-21 00:12:54.000000', NULL, 1),
