(5147600, 747237, 83313, '<td valign="top">Seems a bit washed out. I copied and pasted this into my image editor and found that the histogram for this image is flat on the left hand 1/5 of the chart. A quick levels adjustment really helped this a lot. PM me if you would like me to explain further and show you what I got with it.</td>', 'Seems a bit washed out. I copied and pasted this into my image editor and found that the histogram for this image is flat on the left hand 1/5 of the chart. A quick levels adjustment really helped this a lot. PM me if you would like me to explain further and show you what I got with it.', '2008-12-23 12:10:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5147603, 747220, 83313, '<td valign="top">This is just too quirky for me not to love it!</td>', 'This is just too quirky for me not to love it!', '2008-12-23 12:11:28.000000', NULL, 1),
