(5147615, 746516, 83313, '<td valign="top">Not sure how these catfish fit the topic. Interesting looking though. What was going on here that was making them act this way?</td>', 'Not sure how these catfish fit the topic. Interesting looking though. What was going on here that was making them act this way?', '2008-12-23 12:16:58.000000', NULL, 1),
(5147618, 747996, 83313, '<td valign="top">Looks like the embodiment of the default "grey-guy" avatar on Flickr.</td>', 'Looks like the embodiment of the default "grey-guy" avatar on Flickr.', '2008-12-23 12:18:44.000000', NULL, 1),
(5147622, 747944, 83313, '<td valign="top">Cropped a little tight and tilted a bit, I think, but the main thing is I think your image is suffering from is the effects of excessive JPEG compression. Using less compression and the full 150k allowed (instead of the highly compressed 33k that it is) would have  resulted in a more detailed and snappy image. I can see compression artifacts around the high contrast edges. Most image editors will allow you to adjust the compression when you save the file.</td>', 'Cropped a little tight and tilted a bit, I think, but the main thing is I think your image is suffering from is the effects of excessive JPEG compression. Using less compression and the full 150k allowed (instead of the highly compressed 33k that it is) would have  resulted in a more detailed and snappy image. I can see compression artifacts around the high contrast edges. Most image editors will allow you to adjust the compression when you save the file.', '2008-12-23 12:23:16.000000', NULL, 1),
(5147624, 748013, 83313, '<td valign="top">Not sure what it really is, but I like it and the title fits. A well done semi-abstract. I''m giving it a high vote and hoping to see it toward the top of the challenge.</td>', 'Not sure what it really is, but I like it and the title fits. A well done semi-abstract. I''m giving it a high vote and hoping to see it toward the top of the challenge.', '2008-12-23 12:25:15.000000', NULL, 1),
(5147628, 747776, 83313, '<td valign="top">Very nice. The flower stand out nicely from the background. DOF is just right.</td>', 'Very nice. The flower stand out nicely from the background. DOF is just right.', '2008-12-23 12:26:07.000000', NULL, 1),
(5147888, 747886, 43774, '<td valign="top">One of the best in the challenge, lighting is very effective.</td>', 'One of the best in the challenge, lighting is very effective.', '2008-12-23 15:18:14.000000', NULL, 1),
