(5147947, 747951, 101822, '<td valign="top">I love the shape of the shadow and the nail, a near perfect example of personification - but if I were you, I would change the background colour to blue or pink, blue signifying sadness, or pink signifying ballerina.</td>', 'I love the shape of the shadow and the nail, a near perfect example of personification - but if I were you, I would change the background colour to blue or pink, blue signifying sadness, or pink signifying ballerina.', '2008-12-23 15:56:22.000000', NULL, 1),
(5147955, 747251, 101822, '<td valign="top">This photo isn''t very aesthetically pleasing, and if it werent for the title I would have no idea what it''s supposed to be. The title is helpful, though</td>', 'This photo isn''t very aesthetically pleasing, and if it werent for the title I would have no idea what it''s supposed to be. The title is helpful, though', '2008-12-23 15:59:36.000000', NULL, 1),
